def search_substr(fullText, searchText, allowOverlap=True):
    if not searchText:
        return 0
    if not allowOverlap:
        return fullText.count(searchText)
    count = 0
    n = len(fullText)
    m = len(searchText)
    for i in range(n - m + 1):
        if fullText[i:i+m] == searchText:
            count += 1
    return count
